// Тег @data отправляет тест в проект data (десктоп Chrome), поэтому устройство задано здесь: iPhone 390×844, WebKit, тач.
// Баг был именно на телефоне: переключатель под тетрадью, а режим пера блокирует прокрутку (комментарий программиста 01.11).
// Не прогонять при записи — запуск только по /qa-regress.
import * as path from 'path';
import { devices } from '@playwright/test';
import { test, expect } from '../../fixtures';
import {
  LEVEL1_TASKS,
  annotateCleanup,
  birthYearForAge,
  createChildWithLevels,
  handoverToChildHome,
  openWritingCatalog,
  openWritingTask,
  qaChildName,
  writingSurface,
} from '../writing-submit/writing.helpers';


// Пропущено 08.11 (решение пользователя): тест создаёт нового ребёнка QA-AUTO и передаёт ему устройство — с #8ca267 режим ребёнка серверный и запирает вход до ввода пароля/PIN.
test.skip(true, 'QA-AUTO + режим ребёнка запирает вход (#8ca267) — пропущено по решению 08.11');

test.use({
  browserName: 'webkit',
  viewport: { width: 390, height: 844 },
  isMobile: true,
  hasTouch: true,
  deviceScaleFactor: 3,
  userAgent: devices['iPhone 13'].userAgent,
  storageState: path.resolve(__dirname, '../../../auth/parent.json'),
});

test.describe('Печать в заданиях письма уровня 1 — телефон (autotest-writer)', () => {
  test('390×844: «הקלדה» на первом экране над тетрадью, тап открывает поле печати @iphone @data #493b35', async ({ page }, testInfo) => {
    test.setTimeout(2 * 60_000);
    const name = qaChildName();
    const childId = await createChildWithLevels(page, name, { birthYear: birthYearForAge(6), writingLevel: 1 });
    annotateCleanup(testInfo, name, childId);
    await handoverToChildHome(page, childId, name);
    await openWritingCatalog(page, childId);
    await openWritingTask(page, LEVEL1_TASKS[0]);

    const s = writingSurface(page);
    // Т1.1: переключатель виден на первом экране без прокрутки
    await expect(s.typingMode).toBeVisible();
    await expect(s.typingMode).toBeInViewport();
    await expect(s.handMode).toBeInViewport();

    // «над тетрадью»: низ переключателя выше верха холста
    const sw = await s.typingMode.boundingBox();
    const nb = await s.canvas.boundingBox();
    expect(sw, 'нет boundingBox у «הקלדה»').not.toBeNull();
    expect(nb, 'нет boundingBox у тетради (canvas)').not.toBeNull();
    expect(sw!.y + sw!.height, 'переключатель не над тетрадью').toBeLessThanOrEqual(nb!.y + 1);
    expect(sw!.y + sw!.height, 'переключатель ниже первого экрана').toBeLessThanOrEqual(844);

    // Тап → поле печати (тикет «מה רצוי»: «אפשר לעבור ל"הקלדה"»)
    await s.typingMode.tap();
    await expect(s.typingMode).toHaveAttribute('aria-checked', 'true');
    await expect(s.typingField).toBeVisible();
  });
});
